# activation, platform responsibility, author responsibility, configuration, limits.
MECHANISMS = {
    'run_library': ('operator', 'Server-side paginated summaries by person, Loop, status, and dates; meaningful progress updates activity, and child Runs inherit attribution. Archival preserves history; deletion protects references and live executions.', "Set the caller's name once and pass created_by on creation. Query with filters/next_offset; use metadata_revision to change title, attribution, and archival.", ['call.py profile --name','start_run.created_by','list_runs','update_run','delete_run','archive_loop','delete_loop'], 'Attribution is not an account or permission boundary. Reads/unchanged polling do not refresh activity. Deletion leaves native sessions and external artifacts. Archive referenced Loop versions instead of deleting them.'),
    'loop_calls': ('declared', 'Creates and links child Runs, executes their entries, durably waits in the parent node, and validates returned results. Recovery/retry reuses the same child Run.', 'Declare kind=loop with loop.key/inputs/result for an installed Loop on the same service and input/result-envelope mappings.', ['set_implementation.loop','read_task.execution_state.child_run_id','read_run.parent_call'], 'One Task maps to one child Run; new execution requires a new call Task. Parent/child pause or terminate separately; the child uses its own completion conditions. Ancestor-recursive calls are unsupported.'),
    'team_service': ('configured', 'One service persists team Loops, Runs, and state machines. NAS request/receipt mailboxes and HTTP share the official tools; the web UI is optional.', 'Select a NAS team directory; members save nas:/// addresses using their own mount paths. Read/edit clients do not need the runtime platform installed.', ['serve --team-dir','serve --no-web','call.py --url','call.py result'], 'Only one service opens the team database, using DELETE journaling. NAS must support locking/durable writes. Timeout does not cancel requests; a processing crash returns outcome_unknown without automatic replay. Validate real NAS behavior in deployment.'),
    'headless_execution': ('configured', 'A local scheduler receives assigned processes, persists deduplication/results, and forwards interactive terminals. The service retains business state machines; exact sessions resume on their original executor.', 'Explicitly start a receiver registration. Discover IDs with list_executors and select implementation.executor on a node or named agent. Install required CLIs/environment on the executor.', ['local register/start','list_executors','read_executor_call','implementation.executor'], 'Disconnection does not reassign/restart work. A restarted service reconnects to the original call; a restarted receiver does not replay accepted commands with unknown outcomes. Native session history must remain accessible on the original executor. Legacy NAS/Base named communication remains supported.'),
    'local_scheduling': ('operator', 'Shares a small scheduling, pure-transition, and process-management core for timers, script conditions, and local CLIs without a service, Run, or web UI.', 'Register through loop-anything-local, optionally using NAS for persistent definitions; explicitly select IDs with local start.', ['local --root register/list/show/start/stop'], 'Definitions persist; processes stop with their machine. Loading/moving machines does not restart them. Intervals run after completion; conditions fire once by default. Failure stops with a saved error; receiver communication errors retry at the configured interval.'),
    'flow_agent': ('declared', 'Built-in flow decisions awaken on explicit event routes, reusing execution, sessions, wait/resume, and Timeline writes without extra authored flow nodes.', "Choose decision points from the user's goal, keep full business rules in the Loop handbook, and configure an actual CLI, executor, or dispatch. Do not choose a default progression mode for the user.", ['Loop.flow_agent','nodes.*.routes.flow_agent','read_task.flow_decisions','build_plan/edit_tasks/report_task/finish'], 'Configuring an executor alone does not trigger it. Without a matching route no agent is called. Decisions have global Run scheduling scope with commit validation. Explicit rule and agent routes can both fire; read receipts to avoid duplicate scheduling.'),
    'builtin_flow_agent': ('declared', 'Identifies the built-in decision configuration/route protocol so old services cannot interpret it as ordinary event routing.', 'Package capability declarations detect it automatically; see flow_agent for usage.', ['Loop.flow_agent','nodes.*.routes.flow_agent'], 'A compatibility declaration alone does not awaken an agent; explicit routing is required.'),
    'flow_diagram': ('author-maintained', 'Ships ready-made drawing components/templates in the Skill. Saved package assets appear in the overall workflow view; actual IDs/unique names link diagram nodes to detail panels. Custom shapes can use data-loop-node.', 'After initial construction or changes to nodes, branches, loops, or task generation, draw every defined node, including optional/fallback branches. Do not replace actual nodes with summary boxes; compare against the node list and preview before saving.', ['scripts/render_flow.py','assets/flow.md','docs/flow.md','docs/flow.html','put_asset'], 'Rendering requires Node.js 20+, viewing does not. Diagrams do not change execution rules, awaken agents on page open/every round, or become save/run preflight gates.'),
    'machine_identity': ('automatic', 'Generates and persists a full machine UUID on demand, separate from workspace identity. communication_status.self and awakening contexts expose both directly.', 'Read self and address directory members using instance_id plus agent_id; do not infer identity from MAC, hostname, or session.', ['communication_status.self','context.self','communication_config(operation=identity)'], 'Identity belongs to the connected platform user environment. instance_id aliases workspace_id. Moving/renaming preserves identity; copies need an explicitly new workspace identity without historical takeover. Do not copy identity storage with a business database to another machine.'),
    'communication_context': ('automatic/operator', 'Queries default to compact status/full result. Base logs remain on the executor and paginate on demand (logs_pending means waiting). Resumption/follow-up preserve business context, results, and original session without embedding full communication archives.', 'Read status/structured results first. Pass NAS paths only with confirmed shared access, even with Base communication. Use dispatch references/artifacts.md for optional cloud attachments when needed. Page through logs only for diagnostics.', ['read_assistance.include_logs','read_assistance.include_details','read_assistance.max_chars','read_assistance.after/offset'], 'Logs default to 4000 characters per page, maximum 16000. Successful native-session execution keeps no duplicate full terminal transcript. Scripts, failures, and sessionless execution retain diagnostics. Structured business results are not automatically shortened.'),
    'standalone_collaboration': ('configured/operator', 'A built-in Loop handles standalone collaboration. Event waits record results; current sessions or named coordinators suspend/resume the same Task/session.', 'request_assistance returns a collaboration Run; follow-ups continue it. Automatic resumption uses start_collaboration with the actual local session, agent PID, and resume configuration; after wait_assistance, finish and exit the original process.', ['start_collaboration','request_assistance','wait_assistance'], 'Unknown external sessions receive result tracking/notification only. Never guess sessions or resume alongside a still-live original process.'),
    'confirmed_agent_directory': ('configured', 'Group directories share user-confirmed duties, capabilities, and availability. Legacy unconfirmed descriptions do not accept new group work.', 'Ask about duties and confirm description/group exposure before communication_config(task_confirmed=true). Reconfirm changed descriptions or added groups.', ['communication_config','communication_status'], 'An agent-written description is not user confirmation.'),
    'assistance_session_resume': ('configured/operator', 'Checks the native session/exact resume command before waiting; replies/deadlines resume that session and Task with results and fresh credentials.', 'Configure managed CLI/resume_command and register the actual session. finish only after wait_assistance succeeds; remote nodes also complete their execution request.', ['wait_assistance','register_agent_session','implementations.*.resume_command'], 'Original machine/agent/session stay fixed. Missing data or resume failure blocks explicitly, never starts a new conversation. Current resumption uses macOS/Linux terminals; retain CLI session files.'),
    'group_notifications': ('configured/operator', 'Machines bind their own group outlets. The source durably creates notifications; the selected machine uses existing adapters such as cc-connect and returns receipts.', "Configure named local outlets, then group_notifications to bind each machine's group entry.", ['communication_config(operation=group_notifications)','platform notification channels'], 'Commands/credentials do not enter team transport. Created notifications pin their outlet; old-policy requests finish under it. Verify unknown delivery before explicit retry.'),
    'cc_connect': ('configured/operator', 'Shares local cc-connect configuration, discovers existing Bots without returning credentials, and lets named agents select a Bot directly.', 'Discover with read_cc_connect. If missing, configure_cc_connect with actual config/executable paths. Map notification_bot from returned project/platform; create a cc_connect outlet only for a fixed destination.', ['read_cc_connect','configure_cc_connect','agent.notification_bot','channels.*.cc_connect'], 'Do not guess config directories, write per-Bot commands, or install/start Bots. Listing proves neither online status nor group membership. Ambiguity does not auto-select. Explicit references can be saved without availability preflight. Paths/secrets stay local.'),
    'conversation_notifications': ('automatic/configured', "Feishu-origin calls reply to the original conversation by default. Private chats use the entry Bot; group chats prefer the named agent's Bot while preserving the topic.", 'Skill call.py carries chat_context only. The platform persists/reuses origin; the adapter retains the original entry, uses a known root with cc-connect, or passes an unresolved session unchanged. No Feishu permission/credential lookups. agent.notification_bot maps discovered local Bots; legacy notification_route remains compatible. Nested assistance inherits origin without rebuilding notification commands.', ['request_assistance.chat_context','start_run.chat_context','communication_config(operation=agent)','existing conversation_id compatibility'], 'Notification integration failure does not block business work. Fall back to the entry Bot only after definitive non-delivery (not started, not connected, or explicit rejection), not ambiguous failure. Preserve raw session_key; map an explicit topic to a root target in the same chat/topic, never to the main timeline. cc-connect owns actual delivery. Explicit outlets win; without origin use per-machine group outlets.'),
    'group_notification_priority': ('automatic/configured', 'Without chat origin, each group notification prefers the action machine, then the immediate requester; with neither outlet, record only in the platform.', 'Bind outlets per machine and omit request.notification_route to use priority. Nested assistance falls back to its immediate requester.', ['communication_config(operation=group_notifications)','communication_status.groups[].notification_bindings','read_assistance.notifications[].routing'], 'Fallback requires an absent/explicitly disabled outlet, not offline/failure/unknown delivery. Explicit outlets win; retries pin the original binding.'),
    'timeline_storage': ('automatic', 'Persists Runs, Tasks, attempts, versioned results, events, and history; formal writes share a database transaction.', 'Define business-result schemas and report facts through official tools.', ['nodes.*.outputs','records','report_task.envelope'], 'External side effects are outside local transactions; the platform cannot provide exactly-once submission for an external service.'),
    'task_scheduler': ('automatic', 'Checks inputs/after dependencies, pause points, implementation selection, concurrency, and scope, then dispatches ready Tasks.', 'Declare Tasks, sources, and dependencies; configure routes when successors should be generated automatically.', ['plans.*.steps.*.inputs','plans.*.steps.*.after','settings.max_parallel','nodes.*.routes'], 'Dependency edges advance existing Tasks only; missing business work is not inferred by default.'),
    'execution_recovery': ('automatic', 'Recovers persisted execution state after restart, preserves retry/observation identities, and exposes processes/identities whose stopping cannot be confirmed.', 'Make submission/observation recoverable, investigate unknown external effects, and confirm old processes stopped when needed.', ['implementations.*.observe','implementations.*.lifecycle','command'], 'Unknown process status is not safe completion. External idempotency and identity resolution belong to adapters.'),
    'implementation_selection': ('declared', 'Selects Task override, then Run binding, then Loop default; validates node/candidate parameters and preserves execution snapshots.', 'Provide real candidates, parameter contracts, and entries; determine automatic-stage parameters when scheduling.', ['implementations','settings.bindings','Task.implementation','Task.parameters'], 'The platform does not inject default parameters, generate business commands, or repair execution environments.'),
    'workspace_inspection': ('automatic', 'Provides Loop structure, dependencies, execution state, results, input provenance, history, parameter editing tools, previews, and file-result display.', 'Provide meaningful node names, schema title/description, explicit file outputs, and business results.', ['nodes.*.label','records.*.title','records.*.description','records.*.format'], 'The workspace supports runtime operations; there is no separate sanitized team-only dashboard. Displaying a file does not prove artifact validity.'),
    'agent_communication': ('configured/operator', 'All dispatch reuses loop-anything-dispatch; only receiving needs a running platform. Replies persist in full. Pass NAS artifacts only with shared access; native Feishu attachments are optional and automatically handle oversized inline messages. Base coalesces state, updates heartbeats in place, and archives acknowledged messages in the cloud. Requests/results remain for optional manual cleanup; clients do not auto-copy full bodies. One NAS/Base team link supplies directory/result views. Enabled Base wins; NAS is used only without Base, never to reroute failures. Existing Runs/requests retain transport. Names and IDs resolve through the directory; script wait timeouts do not cancel requests.', "Set the receiving default with communication_config(operation=team,link=...), then expose agents after user-confirmed duties. Send-only clients use the independent Skill's join/leave/agents/submit/read/wait/control. Loop nodes retain scoped entries for registration/dispatch; wait_assistance then finish when needed.", ['communication_config','implementations.*.dispatch','request_assistance','wait_assistance'], 'Dispatch fixes one machine/agent; receivers persist then execute without another source grant. Old in-flight protocols remain compatible; the source owns the business Run. Recovery pins the original session; disconnection never auto-reruns work. Validate actual NAS/Base environments.'),
    'agent_resume': ('configured/operator', 'Shows results per attempt, records actual CLI session IDs, and resumes the selected original session on request with fresh operation identity and preserved historical results.', 'Provide CLI/resume commands; let the CLI output or agent register its real ID. The user selects the target and new request.', ['implementations.*.agent_cli','implementations.*.resume_command','register_agent_session','command argv {{session_id}}'], "Do not guess with --last or scan unrelated CLI history. Native IDs are exclusive across Runs until process exit; users manage manually started external CLIs. Missing old IDs need explicit registration; missing local history can prevent recovery. Resume only running/paused Runs. CLI storage/model access remain the CLI's responsibility."),
    'agent_terminal': ('automatic/configured', 'Streams output; with native sessions it keeps a bounded live tail, then session location after success. Failures/sessionless runs retain diagnostics. Optional terminals attach to the same CLI process, forwarding keyboard/size and closing after finish.', 'Provide CLI, cwd, login, and permissions. Interactive commands receive context through {{prompt}} or {{prompt_file}}.', ['implementations.*.terminal','implementations.*.command','read_capabilities(agent_terminal)'], 'Ordinary command output is read-only; interactive terminals currently support macOS/Linux. After process restart, history/recovery follow existing operation rules without guaranteeing CLI session recovery. Terminal identity/execution checks and report_task/finish still apply. Do not duplicate logging/interaction services.'),
    'host_service': ('configured', 'Keeps the workspace service running on its installed host, with supported keep-awake controls and macOS background hosting.', 'Choose/install the host, database, port, and credentials; configure the host to suit runtime needs.', ['service CLI','platform keep-awake setting'], 'Remote compute, credentials, training environments, and cross-machine deployment belong to installation/business integration.'),
    'authoring': ('operator', 'Saves drafts/revisions, validates definitions, and produces locally usable versions; Runs pin their startup version.', 'Design business nodes/methods, keep editing the existing draft, and export when sharing.', ['Loop.id/version','draft revision'], 'Draft save, usable-version save, and share packaging serve different purposes. Historical Runs do not migrate automatically.'),
    'parameter_contracts': ('automatic', 'Validates nested inputs/outputs and parameters at formal Task writes and implementation selection.', 'Declare actual contracts and use validation tools to locate missing fields.', ['nodes.*.parameter_schema','implementations.*.parameter_schema','records'], 'It does not interpret domain meaning or inject schema.default into parameters.'),
    'conditional_contracts': ('declared', 'Checks conditional requirements, exclusive alternatives, and union types; unsupported schema keywords fail explicitly.', 'Declare deterministic parameter requirements in schemas.', ['parameter_schema.if/then/else','parameter_schema.oneOf','parameter_schema.dependentRequired'], 'Only the published JSON Schema subset is supported; implementations still project business CLI arguments.'),
    'plans': ('declared', 'Allocates Task/output identities, expands each, aggregates collect, resolves inputs/after, and omits steps by when/skip.', 'Define reusable work structure, batch parameters, input mapping, and optional steps.', ['plans.*.parameters','plans.*.steps','steps.*.each/when','inputs.*.from/collect'], "Omission produces no placeholder output; consumers need explicit reusable sources. Plan when applies to a step before that step's each expansion."),
    'event_routes': ('declared', 'Maps accepted node events to plan parameters/expansion, committing with results. Duplicate reports return the same receipt.', 'Declare event, plan, values, and needed each/when/steps; nodes submit business results.', ['nodes.*.routes','report_task.report_id'], 'Only accepted lifecycle reports trigger routes. Do not generate the same successors again in helpers.'),
    'task_refs': ('declared', 'Resolves business refs to actual Task/record identities, including forward references across batches in one report.', 'Provide Run-unique names and explicit aggregation members; include rounds in repeated names.', ['steps.*.ref','steps.*.after_refs','inputs.*.task_ref/task_refs'], 'Missing/duplicate references reject submission. No task-group scheduler infers members automatically.'),
    'record_versions': ('automatic', 'Pins Task-output references to producer versions and preserves actual input provenance; aggregation can consume different record revisions.', 'Declare task_ref/task_refs sources and explicitly specify version overrides.', ['inputs.*.revision/revisions','resolve_refs'], 'Unversioned ordinary record sources use latest-value semantics. Pinning a revision does not verify remote file contents.'),
    'task_edits': ('operator', 'Atomically validates/applies ordered edits against basis and business scope, rolling back the group on failure.', 'Decide from read evidence and reconsider after conflicts.', ['edit_tasks.basis','edit_tasks.changes','edit_tasks.preview'], 'Separate calls are not cross-call transactions. Use routes to commit results and successors together.'),
    'lifecycle': ('declared', 'A generic state machine computes transitions independently; Timeline stores state/results/history and applies same-Task retry, observation failures, and configured fallback in the existing transaction.', 'Adapters report bounded facts; lifecycle declares transitions/retry conditions/business repair methods. No business-specific transition functions or state stores are needed.', ['implementations.*.lifecycle','implementations.*.command/observe','Loop.fallback_node'], 'Existing Loops need no migration. waiting retains external identity, observation timing, and query errors. Healthy queuing/long duration is not automatically failure. Retry, deduplication, and atomicity remain unchanged.'),
    'waits': ('declared', 'Native timer/event/approval Tasks persist waits; external events match by name/correlation key.', 'Declare wait times, event keys, or approvals, and routes for subsequent work.', ['implementations.*.kind','implementations.*.wait','implementations.*.event'], 'Notifications alone do not pause work; waiting needs an explicit Task. Adapters connect chat replies/business event sources.'),
    'notifications': ('configured', 'Queues, deduplicates, and records delivery receipts per outlet. Missing configuration waits; delivery failures remain visible.', 'Configure actual send commands/destinations and declare content/question correlation keys.', ['platform notification channels','settings.notification_route','lifecycle.transitions.*.notify','notify.reply'], 'A platform notification record is not external delivery. The platform does not install chat Bots automatically.'),
    'optimistic_edits': ('automatic/operator', 'Managed identities remember read versions; short commit transactions check basis, scope, and execution state without long Timeline occupancy.', 'Without a sustained token, pass returned basis on edits. Use read_task for focused work and read_timeline/next_tasks for collection/absence decisions. Reconsider conflicts.', ['read_task.basis','read_timeline.basis','edit_tasks.basis','change_task.basis'], 'Do not merely replace version numbers and retry unchanged. Logs/ordinary progress are not conflicts. Identity, same-Task exclusivity, and native-session protection remain, including exit gaps after finish, resumed historical terminals, and unfinished remote processes.'),
    'scopes': ('automatic', 'Restricts changes by Task ownership without excluding concurrent thinking; one valid executor remains per Task.', 'Align ownership with responsibility and finish after completion/explicit waiting. Use an explicit global node for global decisions.', ['Task.parent_id','Loop.global_agent_node','acquire_run/finish'], 'Dependency differs from ownership; ready descendants can run before the parent agent finishes.'),
    'run_control': ('operator', 'Supports pause/resume, Task edits, user requests, and registered waits. Hooks can pause/notify before, after, or at transitions.', 'Choose intervention points/actions from user intent.', ['settings.hooks','command','defer_task','resolve_request'], "The user's agent interprets natural-language authorization; the platform applies explicit operations and scope checks."),
    'termination': ('declared', 'Closes the Run and stops remaining work through completion_rule or termination_signal.', 'Declare decidable conditions or persist a confirmed completion judgment in settings.', ['settings.completion_rule','settings.termination_signal'], 'Business output satisfied/status, an empty Task list, or finish does not end a Run by itself.'),
    'scenarios': ('operator', 'Uses the real Engine in an isolated database with authored simulated reports to check expansion, dependencies, deduplication, and completion.', 'Supply representative inputs, simulated facts, and observable expectations.', ['Loop.scenarios','test_loop','preview_plan'], 'Commands/models/notification delivery are intercepted; this does not replace real environment/model acceptance.'),
    'loop_configuration': ('configured', 'Ships config.example.json; recipient overrides persist separately, are snapshotted for new Runs, and survive retry/restart. Sharing excludes personal overrides.', 'Expose paths/services as startup inputs with documented templates. Recipients use read_loop_config/set_loop_config and explicit bindings after adding local candidates.', ['config.example.json','read_loop_config','set_loop_config'], 'Does not change nodes/routes/lifecycles/Skills, probe availability, or rewrite hardcoded paths. Existing Runs ignore later configuration changes.'),
    'packages': ('operator', 'Packages definitions/candidates/author assets, checks capability requirements, installs versions, and preserves workspace history.', 'Include actual files/dependencies/requirements and target-environment configuration.', ['Loop.requires','package assets','export_loop'], 'The platform does not supply missing business dependencies; installation does not launch a business Run.'),
    'author_skills': ('declared', 'Returns author methods and installed paths by Loop/node binding, preserving relative package structure.', 'Write domain methods, required evidence, inputs/outputs, and completion criteria.', ['Loop.handbook','nodes.*.skills','put_asset'], 'Attaching a script asset does not register an implementation; the platform does not invent business methods.'),
    'runtime_smoke': ('operator', 'Performs explicitly requested real minimal agent startup and simulated lifecycle-report paths.', 'Select authorized candidates/cases and separately validate real external business work.', ['smoke_runtime'], 'May invoke models. Passing static/simulated checks does not establish target-environment readiness.'),
}


def authoring_context():
    return {
        'platform_handles': {
            'execution': 'Persistent Timeline, dependency readiness, concurrent dispatch, operation scopes, execution snapshots, and restart recovery.',
            'composition': 'Parameter contracts, batch template expansion, conditional omission, aggregation, Task/output identities, and stable references.',
            'events': 'Declared lifecycles, report deduplication, atomic results/successors, retries, and configured fallback.',
            'interaction': 'Native waits, pause points, delivery receipts, explicit Run completion, structure/task/result/history views, live output, optional interactive terminals, and native-session resumption.',
        },
        'flow_agent': {'tool': 'read_capabilities', 'arguments': {'capability': 'flow_agent'}, 'reference': 'references/flow-agent.md', 'guidance': 'When converting an existing Skill, suggest flow-agent decisions for uncertain progression and platform execution/waits for deterministic work. Configure explicit points from the user goal, without enabling by default. Read the full Loop handbook, retain runtime records, and do not require every transition to be enumerated in advance.'},
        'flow_diagram': {'tool': 'read_capabilities', 'arguments': {'capability': 'flow_diagram'}, 'reference': 'references/flow-diagram.md', 'guidance': 'After initial construction or changes to nodes, branches, or loops, the building agent updates the overall diagram with bundled render_flow.py and templates. Show every defined node, including optional/fallback branches, rather than summary boxes; compare the node list before saving. Reuse package assets, without new diagram services or mandatory checks.'},
        'loop_configuration': {'tool': 'read_capabilities', 'arguments': {'capability': 'loop_configuration'}, 'reference': 'references/loop-config.md', 'guidance': 'When sharing or moving a Loop, expose paths/services as startup inputs and provide config.example.json. Recipients adapt agents/environments with separate runtime configuration, without copying the workflow or building configuration loaders.'},
        'author_provides': ['Business intent/methods, required deliverables, and allowed actions.', 'Node contracts, candidate implementations, and real external integrations.', 'Declared dependencies/routes/recovery policies, credentials/environment configuration, and acceptance expectations.'],
        'construction_rule': 'When discussing a new or revised Loop, proactively suggest relevant capabilities that change how work is organized and explain their practical benefit. Integrate this into design discussion rather than waiting to be asked. Continue directly when the existing design or explicit user choice fits. Do not recite every feature, add nodes for demonstration, or introduce checks, scores, approvals, or confirmation gates. Consult the opening feature/design map as needed, then relevant activation/configuration details. New scripts should handle business logic or external APIs; state real platform gaps honestly.',
        'details': {'tool':'read_capabilities','arguments':{},'reference':'references/platform-capabilities.md'},
    }


def mechanism_details(name):
    mode,platform,author,configuration,limits = MECHANISMS[name]
    return {'activation':mode,'platform_handles':platform,'author_provides':author,
            'configuration':list(configuration),'limits':limits}


